using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CasinoRoadsideProbe{static CasinoRoadsideProbe(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CasinoRoadsideProbe.request"))return;File.Delete("CasinoRoadsideProbe.request");try{var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var f=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Single(g=>g.name=="billboard (32)");var d=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{f.sharedMesh});File.WriteAllText("FinalEnvironmentRoadReview/CasinoRoadsideBounds.txt",f.GetComponent<Renderer>().bounds+" position="+f.transform.position+"\n"+string.Join("\n",new[]{"Casino raised gold emblem near.asset","Casino raised gold emblem far.asset"}.Select(n=>{var m=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Scenes/Oasis/Casino3DSigns/"+n);return n+" triangles="+m.triangles.Length/3+" bounds="+m.bounds;})));var p=(Vector3[])d.GetType().GetField("p").GetValue(d);var ids=(int[])d.GetType().GetField("ids").GetValue(d);File.WriteAllLines("FinalEnvironmentRoadReview/CasinoRoadsideProbe.txt",Enumerable.Range(0,ids.Length/3).Select(k=>{var a=f.transform.TransformPoint(p[ids[k*3]]);var b=f.transform.TransformPoint(p[ids[k*3+1]]);var c=f.transform.TransformPoint(p[ids[k*3+2]]);var n=Vector3.Cross(b-a,c-a);return new{a,b,c,n};}).Where(t=>t.n.magnitude>5).Select(t=>"area="+t.n.magnitude/2+" normal="+t.n.normalized+" a="+t.a+" b="+t.b+" c="+t.c));}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CasinoRoadsideProbe.txt",e.ToString());}}}

